export const totalDuration = (runs: TestRun[]) => runs.reduce((sum, r) => sum + r.durationMs, 0);
export const hasFailures = (runs: TestRun[]) => runs.some((r) => r.status === 'failed');
export function slowest(runs: TestRun[], count: number): string[] {
  return [...runs]
    .sort((a, b) => b.durationMs - a.durationMs)
    .slice(0, count)
    .map((r) => r.title);
}
